<script setup lang="ts">
import { ref,computed } from 'vue'
import type { AppData,Settings } from '../domain/types'
import type { StockDesk } from '../composables/useStockDesk'
import { parseBackup } from '../domain/snapshot'
import { readBackupFile,pickHostBackup,requestNotifications,enableSound } from '../services/platform'
import BaseDialog from './BaseDialog.vue'
import Icon from './Icon.vue'
const props=defineProps<{desk:StockDesk}>(),emit=defineEmits<{export:[kind:'json'|'watch'|'portfolio'];toast:[message:string]}>()
const settings=computed(()=>props.desk.data.value.settings),fileInput=ref<HTMLInputElement|null>(null),pending=ref<AppData|null>(null),error=ref(''),success=ref('')
function update(patch:Partial<Settings>){try{props.desk.updateSettings(patch);error.value=''}catch(e){error.value=e instanceof Error?e.message:'设置保存失败'}}
async function notification(){try{if(settings.value.notifications){update({notifications:false});return}await requestNotifications();update({notifications:true});emit('toast','系统通知已启用')}catch(e){error.value=e instanceof Error?e.message:'系统通知不可用'}}
async function sound(){try{if(settings.value.sound){update({sound:false});return}await enableSound();update({sound:true});emit('toast','提示音已启用')}catch(e){error.value=e instanceof Error?e.message:'提示音不可用'}}
async function chooseImport(){error.value='';try{const text=await pickHostBackup();if(text===undefined)fileInput.value?.click();else if(text!==null)pending.value=parseBackup(text)}catch(e){error.value=e instanceof Error?e.message:'读取备份失败'}}
async function fileSelected(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;error.value='';try{pending.value=parseBackup(await readBackupFile(file))}catch(e){error.value=e instanceof Error?e.message:'备份无效'}finally{input.value=''}}
async function restore(){if(!pending.value)return;try{props.desk.importData(pending.value);pending.value=null;await props.desk.flush();success.value='备份已恢复；旧行情为缓存，刷新后获取新数据。';emit('toast','数据备份已恢复')}catch(e){error.value=e instanceof Error?e.message:'恢复失败'}}
</script>
<template><section class="settings-view"><div class="page-heading"><div><div class="eyebrow">PREFERENCES</div><h1>设置与备份</h1><p>让工作台适合你的习惯，也让投资记录有据可查。</p></div><span class="version-badge mono">v0.1.0</span></div>
 <p v-if="error" class="form-error settings-error" role="alert">{{error}}</p><p v-if="success" class="success-notice" role="status">{{success}}</p>
 <div class="settings-grid"><section class="surface settings-card"><div class="settings-card-heading"><Icon name="sun" :size="20"/><h2>外观与显示</h2></div><div class="setting-row"><div><strong>界面主题</strong><span>选择深色、浅色或跟随系统</span></div><select :value="settings.theme" aria-label="界面主题" @change="update({theme:($event.target as HTMLSelectElement).value as Settings['theme']})"><option value="dark">深色</option><option value="light">浅色</option><option value="system">跟随系统</option></select></div><div class="setting-row"><div><strong>涨跌颜色</strong><span>配色不改变数值的正负含义</span></div><select :value="settings.colorScheme" aria-label="涨跌颜色" @change="update({colorScheme:($event.target as HTMLSelectElement).value as Settings['colorScheme']})"><option value="red-up">红涨绿跌</option><option value="green-up">绿涨红跌</option></select></div></section>
 <section class="surface settings-card"><div class="settings-card-heading"><Icon name="refresh" :size="20"/><h2>行情刷新</h2></div><div class="setting-row"><div><strong>自动刷新</strong><span>网络失败自动退避，无并行重复请求</span></div><button class="switch" :class="{on:settings.refreshEnabled}" role="switch" :aria-checked="settings.refreshEnabled" aria-label="自动刷新开关" @click="update({refreshEnabled:!settings.refreshEnabled})"><span/></button></div><div class="setting-row"><div><strong>刷新间隔</strong><span>公开数据源可能限流或延时</span></div><select :value="settings.refreshSeconds" aria-label="刷新间隔" @change="update({refreshSeconds:Number(($event.target as HTMLSelectElement).value) as Settings['refreshSeconds']})"><option v-for="seconds in [5,10,15,30,60]" :key="seconds" :value="seconds">{{seconds}} 秒</option></select></div><div class="setting-row"><div><strong>隐藏时节能</strong><span>页面隐藏时跳过行情刷新，提醒也暂停</span></div><button class="switch" :class="{on:settings.pauseWhenHidden}" role="switch" :aria-checked="settings.pauseWhenHidden" aria-label="隐藏时节能" @click="update({pauseWhenHidden:!settings.pauseWhenHidden})"><span/></button></div></section>
 <section class="surface settings-card"><div class="settings-card-heading"><Icon name="bell" :size="20"/><h2>提醒方式</h2></div><div class="setting-row"><div><strong>站内提醒</strong><span>触发记录始终保存，无需权限</span></div><span class="badge accent">已开启</span></div><div class="setting-row"><div><strong>系统通知</strong><span>首次开启需要授予浏览器通知权限</span></div><button class="switch" :class="{on:settings.notifications}" role="switch" :aria-checked="settings.notifications" aria-label="系统通知" @click="notification"><span/></button></div><div class="setting-row"><div><strong>提示音</strong><span>重启后需主动点击重新激活声音</span></div><button class="switch" :class="{on:settings.sound}" role="switch" :aria-checked="settings.sound" aria-label="提醒提示音" @click="sound"><span/></button></div><p class="setting-footnote">关闭插件后不会继续盯盘或通知。本插件没有服务器推送。</p></section>
 <section class="surface settings-card"><div class="settings-card-heading"><Icon name="shield" :size="20"/><h2>数据备份</h2><span class="badge">仅本地</span></div><p class="backup-description">持股、交易、提醒与设置都保存在本机。建议定期备份，恢复前会验证完整账本。</p><div class="backup-buttons"><button class="button subtle" @click="emit('export','json')"><Icon name="download" :size="16"/>导出 JSON 备份</button><button class="button subtle" @click="chooseImport"><Icon name="upload" :size="16"/>导入恢复</button></div><div class="backup-csv"><span>导出 CSV 表格</span><button class="text-button" @click="emit('export','watch')">自选股票</button><button class="text-button" @click="emit('export','portfolio')">持股明细</button></div><input ref="fileInput" class="sr-only" type="file" accept=".json,application/json" aria-label="导入JSON备份" @change="fileSelected"/><p class="setting-footnote">上限 2 MiB · 导入会替换当前数据，不会自动合并。</p><div v-if="desk.unsaved.value||desk.saveError.value" class="storage-warning">{{desk.saveError.value||'数据尚未保存'}}<button class="text-button" @click="desk.retrySave()">重试保存</button></div></section></div>
 <section class="surface about-card"><div class="about-logo"><Icon name="chart" :size="25"/></div><div><h3>股票工作台 <span>OTools Stock Desk</span></h3><p>腾讯财经公开行情 · A 股 / 港股 / 美股 · 私人持股账本</p><p class="muted">行情可能延时、中断或缺失；不提供投资建议，不连接券商，不执行真实交易。数据仅供参考，请以交易所与券商为准。</p></div><span class="version-badge mono">0.1.0</span></section>
 <BaseDialog v-if="pending" title="确认恢复备份" subtitle="验证已通过；请核对记录数量，恢复后将替换当前本地数据" @close="pending=null"><div class="dialog-form"><div class="import-counts"><div><strong>{{pending.watchlist.length}}</strong><span>自选股票</span></div><div><strong>{{pending.trades.length}}</strong><span>交易记录</span></div><div><strong>{{pending.alerts.length}}</strong><span>提醒规则</span></div></div><p class="inline-notice">此操作会覆盖当前数据。请先导出当前备份；备份中的行情只作为缓存展示，不用于触发提醒。</p><div class="dialog-actions"><button class="button subtle" @click="pending=null">取消</button><button class="button primary" @click="restore">确认恢复并替换</button></div></div></BaseDialog>
</section></template>
